from collections import deque
from typing import List

class Solution:
    def shortestDistanceAfterQueries(self, n: int, queries: List[List[int]]) -> List[int]:
        # Initialize graph with initial roads: i -> i+1 for all i from 0 to n-2
        graph = [[] for _ in range(n)]
        for i in range(n - 1):
            graph[i].append(i + 1)

        result = []

        for u, v in queries:
            # Add the new road from u to v
            graph[u].append(v)

            # Find shortest path from 0 to n-1 using BFS
            # Distance from 0 to n-1
            dist = self.bfs(graph, 0, n - 1)
            result.append(dist)

        return result

    def bfs(self, graph, start, end):
        if start == end:
            return 0

        queue = deque([(start, 0)])  # (city, distance)
        visited = set([start])

        while queue:
            city, distance = queue.popleft()

            for neighbor in graph[city]:
                if neighbor == end:
                    return distance + 1

                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, distance + 1))

        return -1  # Should never reach here given the constraints

class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        # Start at position 0 (top-left corner)
        row, col = 0, 0

        # Execute each command
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1

        # Calculate final position using the formula: (row * n) + col
        return row * n + col

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Dictionary to store count of balls by player and color
        player_color_count = {}

        # Initialize for each player
        for i in range(n):
            player_color_count[i] = {}

        # Count balls for each player by color
        for player, color in pick:
            if player not in player_color_count:
                player_color_count[player] = {}
            player_color_count[player][color] = player_color_count[player].get(color, 0) + 1

        # Count winning players
        winning_count = 0

        for player in range(n):
            # Find the maximum count of any single color for this player
            max_count = 0
            if player in player_color_count:
                for color, count in player_color_count[player].items():
                    max_count = max(max_count, count)

            # Player i wins if they have at least (i+1) balls of same color
            if max_count >= player + 1:
                winning_count += 1

        return winning_count

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate flips needed for all rows to be palindromic
        row_flips = 0
        for i in range(m):
            for j in range(n // 2):
                # Compare symmetric positions in row i
                if grid[i][j] != grid[i][n - 1 - j]:
                    row_flips += 1

        # Calculate flips needed for all columns to be palindromic
        col_flips = 0
        for j in range(n):
            for i in range(m // 2):
                # Compare symmetric positions in column j
                if grid[i][j] != grid[m - 1 - i][j]:
                    col_flips += 1

        # Return minimum of row flips and column flips
        return min(row_flips, col_flips)

