from typing import List

class Solution:
    def timeTaken(self, edges: List[List[int]]) -> List[int]:
        n = len(edges) + 1

        # Build adjacency list
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        def simulate(start_node):
            # times[i] = time when node i gets marked
            times = [-1] * n
            times[start_node] = 0

            # Use BFS to propagate markings
            queue = deque([(start_node, 0)])

            while queue:
                node, time = queue.popleft()

                # For each neighbor, check if it can be marked at time + 1
                for neighbor in graph[node]:
                    if times[neighbor] != -1:
                        continue

                    # Check if neighbor can be marked at time + 1
                    if neighbor % 2 == 1:  # odd node - needs marking from time-1
                        # Check if any neighbor of current node was marked at time-1
                        can_mark = False
                        for adj in graph[node]:
                            if times[adj] == time - 1:
                                can_mark = True
                                break

                        if can_mark:
                            times[neighbor] = time + 1
                            queue.append((neighbor, time + 1))
                    else:  # even node - needs marking from time-2
                        # Check if any neighbor of current node was marked at time-2
                        can_mark = False
                        for adj in graph[node]:
                            if times[adj] == time - 2:
                                can_mark = True
                                break

                        if can_mark:
                            times[neighbor] = time + 1
                            queue.append((neighbor, time + 1))

            return max(times)

        # For each starting node, calculate the time when all nodes get marked
        return [simulate(i) for i in range(n)]

